<template><view class="auth"><image class="logo" src="/static/logo.png"/><text class="title">{{registering?'注册听书账号':'登录听见'}}</text><text class="hint">登录后保存收听进度，与听见助手继续你的专属对话。</text><form @submit="submit"><input v-model="username" placeholder="账号（4 至 40 位字母数字或下划线）" maxlength="40"/><input v-model="password" password placeholder="密码（10 至 128 位）" maxlength="128"/><button form-type="submit" :disabled="busy">{{busy?'处理中':registering?'注册并登录':'登录'}}</button></form><text class="error">{{error}}</text><button class="secondary" @click="registering=!registering" :disabled="busy">{{registering?'已有账号，返回登录':'没有账号，立即注册'}}</button><!-- #ifdef MP-WEIXIN --><button class="secondary" @click="store.loginWithWechat">微信登录</button><!-- #endif --><text class="hint" @click="home">返回首页</text></view></template>
<script setup lang="ts">
import {ref} from 'vue';import {useUserStore} from '../../stores/user';import {listeningRequest} from '../../api/listening';
const store=useUserStore(),username=ref(''),password=ref(''),registering=ref(false),busy=ref(false),error=ref('');
function home(){uni.navigateTo({url:'/pages/index/index'})}
async function submit(){if(busy.value)return;busy.value=true;error.value='';try{if(registering.value)await listeningRequest('/api/account/register','POST',{username:username.value,password:password.value});await store.loginWithPassword(username.value,password.value);password.value='';uni.redirectTo({url:'/pages/index/index'})}catch(e:any){error.value=e.message}finally{busy.value=false}}
</script><style scoped>.auth{padding:50rpx;max-width:500px;margin:auto}.logo{width:120rpx;height:120rpx;display:block;margin:30rpx auto}.title{display:block;font-size:40rpx;text-align:center;margin:30rpx}.hint{display:block;color:#789183;font-size:26rpx;line-height:1.8;margin:24rpx 0}input{border:1px solid #dce4d5;padding:24rpx;margin:24rpx 0;border-radius:14rpx;height:auto}button{background:#244f45;color:white;border-radius:14rpx;margin:24rpx 0}.secondary{background:#edf3e8;color:#244f45}.error{color:#a04836;display:block}.auth{background:#fffefa;border:1px solid #e0e6d8;border-radius:24px;margin:35px auto 100px;padding:36px;max-width:450px}.title{font-size:25px;font-weight:500;margin:22px 0}.hint{font-size:12px;color:#859679}.auth input{font-size:13px;padding:15px;border-radius:10px}.auth button{font-size:13px;padding:12px;line-height:1.8;border-radius:10px}.logo{width:70px;height:70px;border-radius:16px}.error{font-size:12px}@media(max-width:600px){.auth{margin:22px 18px 90px;padding:26px}.title{font-size:23px}}</style>
